```go
package main

import (
	"context"
	"fmt"
	"os"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/cognitoidentityprovider"
)

func main() {
	sess := session.Must(session.NewSession(&aws.Config{
		Region: aws.String("us-east-2"),
	}))

	svc := cognitoidentityprovider.New(sess)

	input := &cognitoidentityprovider.ListUsersInGroupInput{
		UserPoolId: aws.String("us-east-2_4YtYz6hV0"),
		GroupName:  aws.String("account:6412003a7a61c0beecdd16a7"),
	}

	result, err := svc.ListUsersInGroup(input)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	var userAttributes []string
	for _, user := range result.Users {
		if *user.Attributes["custom:profileType"] == "1" || *user.Attributes["custom:profileType"] == "2" {
			for _, attr := range user.Attributes {
				userAttributes = append(userAttributes, *attr.Value)
			}
		}
	}

	fmt.Println(userAttributes)
}
```

This code snippet demonstrates how to use the AWS SDK for Go to list users in a specific group and filter them based on the custom attribute `custom:profileType`. The filtered users' attributes are then collected and printed.

Please make sure to replace the `us-east-2_4YtYz6hV0` and `account:6412003a7a61c0beecdd16a7` with your actual user pool ID and group name.

